-- Lock down Supabase's auto-generated PostgREST API, which exposes every
-- public-schema table over HTTP using the anon/authenticated roles unless
-- Row Level Security (RLS) is enabled. This app never uses that API or the
-- Supabase client SDK - all access goes through Prisma via a direct Postgres
-- connection as the table-owning role, which RLS does not restrict (only
-- FORCE ROW LEVEL SECURITY would, and this migration does not set that).
-- With RLS enabled and zero policies defined, the anon/authenticated roles
-- get zero rows back - effectively closing the public API with no app-level
-- changes required.

ALTER TABLE "accounts" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "assets" ENABLE ROW LEVEL SECURITY;
ALTER TABLE "attendance_anomalies" ENABLE ROW LEVEL SECURITY;
